        assert_eq!(rewrite("text \\x1b[38;5;1"), "text \\x1b[38;5;1", "a truncated sequence is left alone");
        assert_eq!(rewrite("38;5;1 plain"), "38;5;1 plain");
        assert_eq!(rewrite("\\x1b"), "\\x1b");
    }

